        getChartData(state) {
            var labels = state.domainState.trustHistory.map(function(_, i) { return 'M' + (i + 1); });
            return {
                governanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.trustHistory },
                        { data: state.domainState.regulatoryHistory },
                        { data: state.domainState.accountabilityHistory },
                        { data: state.domainState.boardIndepHistory },
                        { data: state.domainState.valueHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var procTotal = 0;
            var subTotal = 0;
            var indepTotal = 0;
            history.forEach(function(r) {
                totalScore += (r.results ? r.results.roundScore : 0) || 0;
                procTotal += (r.results ? r.results.procedural : 0) || 0;
                subTotal += (r.results ? r.results.substantive : 0) || 0;
                indepTotal += (r.results ? r.results.independence : 0) || 0;
            });

            var performance = 'Governance Failure';
            if (totalScore >= 85) performance = 'Exceptional Director';
            else if (totalScore >= 70) performance = 'Effective Director';
            else if (totalScore >= 55) performance = 'Developing Director';
            else if (totalScore >= 40) performance = 'Governance Risk';

            var insights = [];
            if (indepTotal >= 16) {
                insights.push('Strong independence: you consistently challenged management when necessary.');
            } else if (indepTotal >= 10) {
                insights.push('Moderate independence: you showed willingness to push back but deferred in some key moments.');
            } else {
                insights.push('Low independence: you tended to defer to management. Effective directors must exercise independent judgment.');
            }
            if (procTotal >= 12) {
                insights.push('Excellent procedural rigor: you followed sound governance processes throughout.');
            } else {
                insights.push('Procedural gaps detected: consider whether you engaged adequate independent advisors and followed proper board process.');
            }
            if (subTotal >= 12) {
                insights.push('Strong substantive judgment across all scenarios.');
            } else {
                insights.push('Review your substantive decisions: some choices may not have optimally balanced monitoring and advisory functions.');
            }

            var lastResult = history[history.length - 1].results || {};
            return {
                totalScore: totalScore,
                proceduralTotal: procTotal,
                substantiveTotal: subTotal,
                independenceTotal: indepTotal,
                performance: performance,
                shareholderTrust: lastResult.shareholderTrust || 50,
                regulatoryCompliance: lastResult.regulatoryCompliance || 50,
                managementAccountability: lastResult.managementAccountability || 50,
                boardIndependence: lastResult.boardIndependence || 50,
                stakeholderValue: lastResult.stakeholderValue || 50,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            if (results.roundScore >= 16) return window.mySimulation.t('hint_excellent');
            if (results.roundScore >= 10) return window.mySimulation.t('hint_good');
            if (results.roundScore >= 4) return window.mySimulation.t('hint_weak');
            return window.mySimulation.t('hint_failure');
        }

