            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('scenarioTitle');
            if (titleEl && window.mySimulation) {
                titleEl.textContent = window.mySimulation.t(round.titleKey);
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) {
                briefEl.textContent = window.mySimulation.t(round.briefingKey);
            }

            for (var i = 0; i < 4; i++) {
                var labelEl = document.getElementById('optionLabel' + (i + 1));
                if (labelEl && window.mySimulation) {
                    labelEl.textContent = window.mySimulation.t(round.optionKeys[i]);
                }
            }
        }
